    verify: "ip -s link show dev ens33\ntc -s qdisc show dev ens33\nsudo ethtool -S ens33 | grep -Ei 'drop|miss|error' | head -30\nsudo tcpdump -c 1000 -nni ens33 'ip or ip6' >/dev/null", expected: ["Counter deltas identify the earliest layer showing loss or pressure.", "Checksum/large-packet anomalies are reconciled with offload state or a second capture point."],
