    mechanics: [["Prerouting", "Runs after ingress before the route decision; commonly used for DNAT and marks."], ["Input", "Filters traffic destined to a local socket."], ["Forward", "Filters traffic routed through the host."], ["Output", "Handles locally generated traffic before final egress processing."], ["Postrouting", "Runs after route selection; commonly used for SNAT/masquerade."], ["Conntrack", "Tracks bidirectional flow tuples and states such as NEW, ESTABLISHED, RELATED, INVALID."]],
